def product_of_nonzero_digits(n: int) -> int:
    n = abs(n)
    if n == 0:
        return 0
    product = 1
    while n:
        n, digit = divmod(n, 10)
        if digit:
            product *= digit
    return product

def alternating_digit_sum(n: int) -> int:
    total = 0
    for i, ch in enumerate(str(abs(n))):
        digit = int(ch)
        total += digit if i % 2 == 0 else -digit
    return total

def is_harshad_number(n: int) -> bool:
    if n <= 0:
        return False
    digit_sum = sum(int(ch) for ch in str(n))
    return n % digit_sum == 0

def reverse_integer_digits(n: int) -> int:
    sign = -1 if n < 0 else 1
    return sign * int(str(abs(n))[::-1])

