def sum_of_proper_divisors(n: int) -> int:
    if n <= 1:
        return 0
    total = 1
    for d in range(2, isqrt(n) + 1):
        if n % d == 0:
            total += d
            other = n // d
            if other != d:
                total += other
    return total

def is_narcissistic_number(n: int) -> bool:
    if n < 0:
        return False
    digits = str(n)
    power = len(digits)
    return sum(int(ch) ** power for ch in digits) == n

def repeated_digit_sum_root(n: int) -> int:
    if n == 0:
        return 0
    return 1 + (n - 1) % 9

