def triangular_number_index(n: int) -> int:
    if n < 0:
        return -1
    disc = 8 * n + 1
    root = isqrt(disc)
    if root * root != disc:
        return -1
    return (root - 1) // 2

def is_palindrome_in_base(n: int, base: int) -> bool:
    digits = []
    while n:
        n, r = divmod(n, base)
        digits.append(r)
    return digits == digits[::-1]

def max_adjacent_digit_gap(n: int) -> int:
    digits = [int(ch) for ch in str(abs(n))]
    return max((abs(a - b) for a, b in zip(digits, digits[1:])), default=0)

def prime_factorization_string(n: int) -> str:
    parts = []
    p = 2
    while p * p <= n:
        if n % p == 0:
            k = 0
            while n % p == 0:
                n //= p
                k += 1
            parts.append(f"{p}^{k}" if k > 1 else str(p))
        p += 1
    if n > 1:
        parts.append(str(n))
    return " * ".join(parts)

def int_to_base_string(n: int, base: int) -> str:
    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    out = []
    while n:
        n, r = divmod(n, base)
        out.append(alphabet[r])
    return sign + "".join(reversed(out))

def parse_base_digits(s: str, base: int) -> int:
    if not s:
        return -1
    value = 0
    for ch in s.upper():
        if "0" <= ch <= "9":
            digit = ord(ch) - ord("0")
        elif "A" <= ch <= "Z":
            digit = ord(ch) - ord("A") + 10
        else:
            return -1
        if digit >= base:
            return -1
        value = value * base + digit
    return value

