def euler_totient_value(n: int) -> int:
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def primes_between_inclusive(lo: int, hi: int) -> list[int]:
    if hi < 2 or hi < lo:
        return []
    sieve = bytearray([1]) * (hi + 1)
    sieve[0] = sieve[1] = 0
    p = 2
    while p * p <= hi:
        if sieve[p]:
            sieve[p * p::p] = bytearray(len(range(p * p, hi + 1, p)))
        p += 1
    return [i for i in range(max(lo, 2), hi + 1) if sieve[i]]

def next_palindromic_number(n: int) -> int:
    s = str(n + 1)
    length = len(s)
    half = s[: (length + 1) // 2]

    def mirror(h: str) -> int:
        return int(h + h[: length // 2][::-1])

    candidate = mirror(half)
    if candidate >= n + 1:
        return candidate
    bumped = str(int(half) + 1)
    if len(bumped) > len(half):
        return 10 ** length + 1
    return mirror(bumped)

