def numbers_with_exactly_k_divisors(limit: int, k: int) -> list[int]:
    if limit < 1:
        return []
    counts = [0] * (limit + 1)
    for d in range(1, limit + 1):
        for multiple in range(d, limit + 1, d):
            counts[multiple] += 1
    return [n for n in range(1, limit + 1) if counts[n] == k]

def longest_collatz_start(limit: int) -> int:
    steps = {1: 0}

    def chain_length(n: int) -> int:
        path = []
        while n not in steps:
            path.append(n)
            n = n // 2 if n % 2 == 0 else 3 * n + 1
        length = steps[n]
        for value in reversed(path):
            length += 1
            steps[value] = length
        return length

    best_start, best_steps = 1, 0
    for s in range(2, limit + 1):
        length = chain_length(s)
        if length > best_steps:
            best_start, best_steps = s, length
    return best_start

