def goldbach_smallest_pair(n: int) -> Optional[tuple[int, int]]:
    if n <= 2 or n % 2:
        return None

    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        return all(x % d for d in range(3, isqrt(x) + 1, 2))

    for p in range(2, n // 2 + 1):
        if is_prime(p) and is_prime(n - p):
            return (p, n - p)
    return None

def next_digit_permutation(n: int) -> int:
    digits = list(str(n))
    i = len(digits) - 2
    while i >= 0 and digits[i] >= digits[i + 1]:
        i -= 1
    if i < 0:
        return -1
    j = len(digits) - 1
    while digits[j] <= digits[i]:
        j -= 1
    digits[i], digits[j] = digits[j], digits[i]
    digits[i + 1:] = reversed(digits[i + 1:])
    return int("".join(digits))

def decimal_period_length(den: int) -> int:
    for p in (2, 5):
        while den % p == 0:
            den //= p
    if den == 1:
        return 0
    k, remainder = 1, 10 % den
    while remainder != 1:
        remainder = remainder * 10 % den
        k += 1
    return k

def gray_code_to_int(g: int) -> int:
    n = 0
    while g:
        n ^= g
        g >>= 1
    return n

