def classify_by_divisor_sum(n: int) -> str:
    s = 0
    if n > 1:
        s = 1
        for d in range(2, isqrt(n) + 1):
            if n % d == 0:
                s += d
                if d != n // d:
                    s += n // d
    if s == n:
        return "perfect"
    return "abundant" if s > n else "deficient"

from functools import lru_cache


def count_with_digit_sum(limit: int, target: int) -> int:
    if target < 0:
        return 0
    digits = list(map(int, str(limit)))

    @lru_cache(maxsize=None)
    def go(pos: int, remaining: int, tight: bool) -> int:
        if remaining < 0:
            return 0
        if pos == len(digits):
            return 1 if remaining == 0 else 0
        top = digits[pos] if tight else 9
        return sum(go(pos + 1, remaining - d, tight and d == top) for d in range(top + 1))

    return go(0, target, True)

def power_tower_mod(bases: list[int], m: int) -> int:
    def totient(n: int) -> int:
        result, p = n, 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    def capped(i: int, cap: int) -> int:
        """min(tower from index i, cap), for cap >= 1."""
        if i == len(bases):
            return min(1, cap)
        a = bases[i]
        if a == 1:
            return 1
        exponent = capped(i + 1, cap)
        value = 1
        for _ in range(exponent):
            value *= a
            if value >= cap:
                return cap
        return value

    def solve(i: int, mod: int) -> int:
        if mod == 1:
            return 0
        if i == len(bases):
            return 1
        phi = totient(mod)
        exponent = capped(i + 1, phi)
        if exponent >= phi:
            exponent = solve(i + 1, phi) + phi
        return pow(bases[i], exponent, mod)

    return solve(0, m) % m

