def count_squarefree_up_to(n: int) -> int:
    if n <= 0:
        return 0
    root = isqrt(n)
    mobius = [1] * (root + 1)
    is_composite = bytearray(root + 1)
    for p in range(2, root + 1):
        if not is_composite[p]:
            for multiple in range(p, root + 1, p):
                if multiple > p:
                    is_composite[multiple] = 1
                mobius[multiple] = -mobius[multiple]
            for multiple in range(p * p, root + 1, p * p):
                mobius[multiple] = 0
    return sum(mobius[d] * (n // (d * d)) for d in range(1, root + 1) if mobius[d])

