def discrete_log_mod_prime(g: int, h: int, p: int) -> int:
    h %= p
    if h == 1 % p:
        return 0
    n = isqrt(p - 1) + 1
    baby = {}
    value = 1
    for j in range(n):
        baby.setdefault(value, j)
        value = value * g % p
    giant = pow(g, -n, p)
    gamma = h
    for i in range(n + 1):
        j = baby.get(gamma)
        if j is not None:
            return i * n + j
        gamma = gamma * giant % p
    return -1

def smallest_number_with_digit_product(p: int) -> int:
    if p == 0:
        return 10
    if p == 1:
        return 1
    digits = []
    for d in range(9, 1, -1):
        while p % d == 0:
            digits.append(d)
            p //= d
    if p != 1:
        return -1
    return int("".join(map(str, sorted(digits))))

def to_negabinary_string(n: int) -> str:
    if n == 0:
        return "0"
    bits = []
    while n:
        remainder = n & 1
        bits.append(str(remainder))
        n = (n - remainder) // -2
    return "".join(reversed(bits))
